    let curr = dummy;
    let p1 = poly1, p2 = poly2;
    while (p1 && p2) {
        if (p1.power > p2.power) {
            curr.next = { coefficient: p1.coefficient, power: p1.power, next: null };
            curr = curr.next;
            p1 = p1.next;
        } else if (p2.power > p1.power) {
            curr.next = { coefficient: p2.coefficient, power: p2.power, next: null };
            curr = curr.next;
            p2 = p2.next;
        } else {
            const sumCoef = p1.coefficient + p2.coefficient;
            if (sumCoef !== 0) {
                curr.next = { coefficient: sumCoef, power: p1.power, next: null };
                curr = curr.next;
            }
            p1 = p1.next;
            p2 = p2.next;
        }
    }
    while (p1) {
        curr.next = { coefficient: p1.coefficient, power: p1.power, next: null };
        curr = curr.next;
        p1 = p1.next;
    }
    while (p2) {
        curr.next = { coefficient: p2.coefficient, power: p2.power, next: null };
        curr = curr.next;
